import{_ as i,C as s,o as d,c as g,a0 as o,b as n,w as e,a as r,E as l,a1 as c}from"./chunks/framework.DhQjJcnt.js";const k=JSON.parse('{"title":"Grill, review và trách nhiệm người","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/grill-and-human-review.md","filePath":"workflows/grill-and-human-review.md"}'),h={name:"workflows/grill-and-human-review.md"};function p(u,t,m,b,A,y){const a=s("Mermaid");return d(),g("div",null,[t[2]||(t[2]=o(`<h1 id="grill-review-va-trach-nhiem-nguoi" tabindex="-1">Grill, review và trách nhiệm người <a class="header-anchor" href="#grill-review-va-trach-nhiem-nguoi" aria-label="Permalink to &quot;Grill, review và trách nhiệm người&quot;">​</a></h1><p><strong>Phạm vi (SSOT):</strong> member <strong>review, grill, chốt</strong>; AI không thay PO; <strong>chất</strong> (grill / reasoning) vs <strong>lượng</strong> (audit script <code>gaps[]</code> / <code>confirms[]</code>).</p><p><strong>Không viết ở đây:</strong> tham số lệnh audit → <a href="./../references/cli-and-commands.html#audit--harness-pr-workflow">references/cli-and-commands.md</a> · tag QA → <a href="./../artifacts/dsl.html">artifacts/dsl.md</a>.</p><p><strong>Bối cảnh lane:</strong> <a href="./design.html">design.md</a> · API/test grill: <a href="./backend.html">backend.md</a>, <a href="./test.html">test.md</a> · mốc gate: <a href="./gates.html">gates.md</a>.</p><hr><h2 id="triet-ly-mot-cau" tabindex="-1">Triết lý một câu <a class="header-anchor" href="#triet-ly-mot-cau" aria-label="Permalink to &quot;Triết lý một câu&quot;">​</a></h2><p><strong>Tool cung cấp SSOT, skill, audit/gate có mã lỗi — team chọn chạy đúng luồng, đọc gap, và chốt quyết định.</strong></p><p>AI <strong>chuẩn hóa</strong> YAML/IR; member <strong>review</strong> Markdown + prototype trực quan. Tool <strong>không</strong> cam kết zero bug nếu bỏ grill/audit hoặc merge gate “cho có”.</p><table tabindex="0"><thead><tr><th>Tool (product)</th><th>Team (out of product)</th></tr></thead><tbody><tr><td>Skills <code>/spec</code>, <code>/update-spec</code>, <code>/testcase</code>, <code>flowgrid audit *</code>, <code>cases:gate</code>, <code>testcase:gen</code></td><td>Chạy skill khi cần; đọc gap JSON; grill nghiệp vụ</td></tr><tr><td>AskQuestion + <code>qa/open</code></td><td>Chọn Recommended / Other / <strong>Log as Tech Debt</strong></td></tr><tr><td><code>/update-spec</code> + re-audit trong skill</td><td>Cập nhật <code>TC-*.yaml</code> sau CR; QA manual E2E (policy team)</td></tr></tbody></table><p><strong>Out of scope product:</strong> deploy/CI, ALM/sprint, dashboard “ai quên grill”, bắt PM full BQA trước sketch nhanh.</p><table tabindex="0"><thead><tr><th>Tình huống</th><th>Ai chịu trách nhiệm</th></tr></thead><tbody><tr><td>Bỏ grill/audit khi skill yêu cầu</td><td>Member + lead</td></tr><tr><td><code>/update-spec</code> không sync TC / traceability</td><td>Author CR + QA</td></tr><tr><td>Matrix Playwright sơ sài</td><td>Author test + <code>/grill-test</code></td></tr><tr><td>Release lọt bug do bỏ bước</td><td>Process người — tool không cam kết zero bug</td></tr></tbody></table><hr><h2 id="script-luong-vs-agent-chat" tabindex="-1">Script (lượng) vs Agent (chất) <a class="header-anchor" href="#script-luong-vs-agent-chat" aria-label="Permalink to &quot;Script (lượng) vs Agent (chất)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        YÊU CẦU SPEC / TC / API</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>        ┌───────────┴───────────┐</span></span>
<span class="line"><span>        ▼                       ▼</span></span>
<span class="line"><span>  DETERMINISTIC AUDIT      AI AGENT (GRILL)</span></span>
<span class="line"><span>  gaps[] · confirms[]      logic nghiệp vụ, zone,</span></span>
<span class="line"><span>  UX_* · FEBE_*            nhất quán UI↔API↔TC</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Output audit</th><th>Ai xử lý</th></tr></thead><tbody><tr><td><code>gaps[]</code> (required thiếu)</td><td>Agent bổ sung bundle/YAML (hoặc member chỉ đường)</td></tr><tr><td><code>confirms[]</code> (optional)</td><td><strong>AskQuestion</strong> từng câu — ≥3 lựa chọn, có <strong>Log as Tech Debt</strong></td></tr><tr><td><code>gaps[]</code> + <code>confirms[]</code> <strong>≥ 10</strong></td><td><strong>Hard stop</strong> — lập Implementation Plan chia phase (3–5 item/phase), không spam chat</td></tr></tbody></table><p><strong>Page type</strong> trước <code>flowgrid audit spec</code>: đọc <code>gen.codegen.profile</code> hoặc suy từ prompt — luôn truyền <code>--type</code>.</p><table tabindex="0"><thead><tr><th>Gợi ý prompt</th><th><code>pageType</code></th></tr></thead><tbody><tr><td>danh sách, list, bảng</td><td><code>list</code></td></tr><tr><td>tạo mới, form, nhập</td><td><code>create</code></td></tr><tr><td>chi tiết, xem</td><td><code>detail</code></td></tr><tr><td>đăng nhập, login</td><td><code>auth</code></td></tr><tr><td>CRUD, quản lý danh mục</td><td><code>admin-crud</code></td></tr></tbody></table><p><strong>UX affordance</strong> (<code>UX_*</code>, <code>CONFIRM_UX_*</code>, <code>uxAffordanceGaps</code> trong JSON): delete confirm, <code>disabledReason</code>, filter+pagination, breadcrumb detail — khớp rule UX chung trong harness.</p><hr><h2 id="luong-spec-audit-zone-sequence" tabindex="-1">Luồng <code>/spec</code> + audit + zone (sequence) <a class="header-anchor" href="#luong-spec-audit-zone-sequence" aria-label="Permalink to &quot;Luồng \`/spec\` + audit + zone (sequence)&quot;">​</a></h2>`,20)),(d(),n(c,null,{default:e(()=>[l(a,{id:"mermaid-216",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20Member%20as%20Member%0A%20%20%20%20participant%20Agent%20as%20AI%20Agent%0A%20%20%20%20participant%20Script%20as%20audit%20spec%0A%20%20%20%20participant%20Bundle%20as%20*.bundle.yaml%0A%20%20%20%20participant%20Wizard%20as%20AskQuestion%0A%0A%20%20%20%20Member-%3E%3EAgent%3A%20%2Fspec%0A%20%20%20%20Agent-%3E%3EAgent%3A%20Page%20type%20detection%0A%20%20%20%20Agent-%3E%3EScript%3A%20audit%20spec%20--type%20pageType%0A%20%20%20%20Script--%3E%3EAgent%3A%20gaps%5B%5D%2C%20confirms%5B%5D%0A%0A%20%20%20%20alt%20gaps%20%2B%20confirms%20%3E%3D%2010%0A%20%20%20%20%20%20%20%20Agent--%3E%3EMember%3A%20Plan%20chia%20phase%20(hard%20stop)%0A%20%20%20%20else%20scope%20nh%E1%BB%8F%0A%20%20%20%20%20%20%20%20loop%20gaps%0A%20%20%20%20%20%20%20%20%20%20%20%20Agent-%3E%3EBundle%3A%20b%E1%BB%95%20sung%20required%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20loop%20confirms%0A%20%20%20%20%20%20%20%20%20%20%20%20Agent-%3E%3EWizard%3A%20AskQuestion%20(Recommended%20%2F%20Other%20%2F%20Tech%20Debt)%0A%20%20%20%20%20%20%20%20%20%20%20%20Wizard--%3E%3EBundle%3A%20c%E1%BA%ADp%20nh%E1%BA%ADt%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20end%0A%0A%20%20%20%20loop%20Zone-by-zone%20(Header%2C%20Toolbar%2C%20Table%2C%20Footer%E2%80%A6)%0A%20%20%20%20%20%20%20%20Agent-%3E%3EBundle%3A%20ho%C3%A0n%20thi%E1%BB%87n%20t%E1%BB%ABng%20zone%20%2F%20turn%0A%20%20%20%20end%0A%0A%20%20%20%20Member-%3E%3EAgent%3A%20%2Fgrill-bqa%20%C2%B7%20%2Fgrill-dev%20%C2%B7%20%2Fgrill-docs%0A%20%20%20%20Agent-%3E%3EScript%3A%20re-run%20audit%0A%20%20%20%20Agent-%3E%3EMember%3A%20grill%20theo%20zone%2C%20ch%E1%BB%91t%20design%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[r(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=o('<h3 id="zone-based-analysis-chong-lost-in-the-middle" tabindex="-1">Zone-based analysis (chống lost-in-the-middle) <a class="header-anchor" href="#zone-based-analysis-chong-lost-in-the-middle" aria-label="Permalink to &quot;Zone-based analysis (chống lost-in-the-middle)&quot;">​</a></h3><p>Trang lớn: <strong>không</strong> all-in-one một prompt — chia <strong>zone</strong> (ví dụ list: Header → Search/Filter → Table → Pagination/Empty) · một turn / zone.</p><p>Grill: hỏi phản biện <strong>theo zone</strong> (ví dụ filter timezone, format tiền tệ cột).</p><hr><h2 id="design-grill-chain" tabindex="-1">Chuỗi grill Design (BQA → Dev → dry → prototype) <a class="header-anchor" href="#design-grill-chain" aria-label="Permalink to &quot;Chuỗi grill Design (BQA → Dev → dry → prototype) {#design-grill-chain}&quot;">​</a></h2><p>Sau <code>/spec</code> hoặc <code>/legacy /spec</code> — khớp <a href="./design.html#design-cycle">design cycle</a>; diagram dưới chỉ <strong>nhánh grill</strong> trước prototype.</p>',6)),(d(),n(c,null,{default:e(()=>[l(a,{id:"mermaid-233",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22Entry%5Cn%2Flegacy%20%2Fspec%20or%20%2Fspec%22%5D%0A%20%20BQA%5B%22%2Fgrill-bqa%5CnStep%20A%20fact-lock%5CnStep%20B%20AskQuestion%22%5D%0A%20%20DEV%5B%22%2Fgrill-dev%5Cnbundle.gen%20%2B%2001%20action%22%5D%0A%20%20DOCS%5B%22%2Fgrill-docs%5Cnoptional%20reconcile%22%5D%0A%20%20DRY%5B%22flowgrid%20gen%3Adry%5Cnir%2Fdesign.yaml%22%5D%0A%20%20PROTO%5B%22%2Fprototype%22%5D%0A%20%20IN%20--%3E%20BQA%0A%20%20BQA%20--%3E%20DEV%0A%20%20DEV%20--%3E%20DRY%0A%20%20DEV%20-.-%3E%7CBQA%E2%86%94Dev%20conflict%7C%20DOCS%0A%20%20DOCS%20--%3E%20DRY%0A%20%20DRY%20--%3E%20PROTO%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[r(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=o('<p><strong>Câu hỏi treo:</strong> <strong>không</strong> dùng <code>openQuestions</code> trên bundle/YAML. AskQuestion → ghi field đã chốt, hoặc <code>qa/open/QA-&lt;bundle.id&gt;-NNNN.yaml</code> rồi <code>/qa-resolve</code> (tag <code>#tech-debt:QA-*</code> — <a href="./../artifacts/dsl.html">artifacts/dsl.md</a>).</p><h3 id="load-policy-agent" tabindex="-1">Load policy (agent) <a class="header-anchor" href="#load-policy-agent" aria-label="Permalink to &quot;Load policy (agent)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Phase</th><th>Load</th><th>Không load / không làm</th></tr></thead><tbody><tr><td><code>/grill-bqa</code></td><td>Toàn bộ <code>ir/design.yaml</code> (layout/copy) + <code>ir/spec.yaml</code> prose</td><td>Sửa tay <code>ir/*</code>; invent field</td></tr><tr><td><code>/grill-dev</code></td><td><code>ir/design.yaml</code> + sibling <code>api/&lt;seq&gt;/01</code></td><td><code>bundle.spec.api</code>; dùng <code>ir/spec.yaml</code> làm codegen input</td></tr><tr><td><code>/grill-docs</code></td><td>Bundle + IR reconcile (BQA ↔ Dev)</td><td>Archaeology lại từ đầu</td></tr></tbody></table><p>Skill harness: <a href="./../references/skills/grill-bqa.html">references/skills/grill-bqa</a>, <a href="./../references/skills/grill-dev.html">grill-dev</a>, <a href="./../references/skills/grill-docs.html">grill-docs</a>, <a href="./../references/skills/qa-resolve.html">qa-resolve</a>.</p><h3 id="grillstatus-tren-bundle" tabindex="-1"><code>grillStatus</code> (trên bundle) <a class="header-anchor" href="#grillstatus-tren-bundle" aria-label="Permalink to &quot;`grillStatus` (trên bundle)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Set bởi</th></tr></thead><tbody><tr><td><code>bqaFacts</code> / <code>bqaOpen</code></td><td><code>/grill-bqa</code></td></tr><tr><td><code>dev</code></td><td><code>/grill-dev</code> khi <code>codegen.profile</code> + entity/module + <code>01</code> <code>action</code> đủ — <code>flowgrid split</code> <strong>fail</strong> nếu <code>done</code> thiếu</td></tr></tbody></table><p>Delta sau pilot: <code>/update-spec</code> → re-audit spec → grill lại nếu cần — <a href="./gates.html">gates.md</a>.</p><hr><h2 id="grill-theo-vai-tro-tom-tat" tabindex="-1">Grill theo vai trò (tóm tắt) <a class="header-anchor" href="#grill-theo-vai-tro-tom-tat" aria-label="Permalink to &quot;Grill theo vai trò (tóm tắt)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Trọng tâm</th></tr></thead><tbody><tr><td><code>/grill-bqa</code></td><td>Nghiệp vụ, validation, user story, UX affordance</td></tr><tr><td><code>/grill-dev</code></td><td><code>bundle.gen</code>, actions, <code>#gen:*</code>, <code>#needs-component</code>, split <code>ir/design</code></td></tr><tr><td><code>/grill-docs</code></td><td>Hòa giải BQA ↔ Dev — <strong>không</strong> thay từng grill riêng</td></tr><tr><td><code>/grill-prototype</code></td><td>UI vs spec, mock boundary, testIds</td></tr><tr><td><code>/grill-api</code> / <code>/grill-api-spec</code></td><td>Contract BE, security shape cho <code>/wire</code></td></tr><tr><td><code>/grill-test</code></td><td>Matrix spec ↔ TC ↔ Playwright — audit, không regen hàng loạt</td></tr></tbody></table><p><code>/qa-resolve</code> đóng <code>qa/open/QA-*</code> — không hallucinate câu treo trên bundle.</p><hr><h2 id="truoc-codegen-—-quy-uoc-grill" tabindex="-1">Trước codegen — quy ước grill <a class="header-anchor" href="#truoc-codegen-—-quy-uoc-grill" aria-label="Permalink to &quot;Trước codegen — quy ước grill&quot;">​</a></h2><p>Ràng buộc chi tiết nằm trong skill (<code>harness/docs/skills/…</code>, <code>harness/tests/skills/…</code>) và output <code>flowgrid audit *</code>. Bảng dưới tóm tắt hành vi thường gặp khi chạy lane Design tới codegen.</p><table tabindex="0"><thead><tr><th>Chủ đề</th><th>Quy ước</th></tr></thead><tbody><tr><td>Page type</td><td><code>/spec</code> / grill gọi <code>flowgrid audit spec --type &lt;pageType&gt;</code> — output <code>gaps[]</code> / <code>confirms[]</code></td></tr><tr><td>Khối lượng confirms</td><td>Tổng <code>gaps</code> + <code>confirms</code> ≥ 10 → skill dừng, lập plan phase (không hỏi lẻ tẻ)</td></tr><tr><td>Trang lớn</td><td>Phân <strong>zone</strong> — một turn / zone (tránh lost-in-the-middle)</td></tr><tr><td>Chuỗi Design</td><td>BQA → Dev → (<code>/grill-docs</code> nếu conflict) → <code>gen:dry</code> — <a href="#design-grill-chain">§ design grill chain</a></td></tr><tr><td>Gap chưa chốt</td><td>Ghi <code>qa/open/QA-*</code> hoặc xử lý trong bundle — không invent</td></tr><tr><td>Sau <code>/update-spec</code></td><td>Skill yêu cầu <strong>re-audit spec</strong> trước split/merge an toàn</td></tr></tbody></table><p>Mốc audit/gate theo lane: <a href="./gates.html">gates.md</a>.</p>',16))])}const v=i(h,[["render",p]]);export{k as __pageData,v as default};
